SELECT psd.`id`, psd.`material_code`,
/*物资总需信息*/ tdd.id AS totalId, tdd.material_tech_param, tdd.material_standard, tdd.total_demand_amount, tdd.self_demand_amount, tdd.category_name, /*优先进场物资信息*/ pad.id AS padId, pad.prior_approach_num,
psd.`purchase_supply_id`, psd.`brand`, psd.`non_prior_approach_amount`, psd.`batch`, psd.`plan_purchase_num`, psd.`plan_purchase_date`, psd.`source`, psd.`currency`, psd.`unit_price`, psd.`avg_purchase_price`, psd.`avg_despatch_price`, psd.`avg_cust_clear_price`, psd.`avg_local_transport_price`, psd.`avg_landing_price`, psd.`total_price`, psd.`file_group_id`, psd.`remark`, psd.`project_id`, psd.`project_name`, psd.`dept_id`, psd.`create_user`, psd.`create_user_name`, psd.`create_time`, psd.`update_user`, psd.`update_user_name`, psd.`update_time`, psd.`del_user`, psd.`del_time`, psd.`del_flag`, psd.`pt_var1`, psd.`pt_var2`, psd.`pt_var3`, batch.id as batchId, batch.purchase_supply_id as b_purchase_supply_id, batch.purchase_supply_detail_id as b_purchase_supply_detail_id, batch.project_id as b_project_id, batch.batch as b_batch, batch.plan_purchase_num as b_plan_purchase_num, batch.plan_purchase_date as b_plan_purchase_date, batch.source as b_source, batch.currency as b_currency, batch.unit_price as b_unit_price, batch.avg_purchase_price as b_avg_purchase_price, batch.avg_despatch_price as b_avg_despatch_price, batch.avg_cust_clear_price as b_avg_cust_clear_price, batch.avg_local_transport_price as b_avg_local_transport_price, batch.avg_landing_price as b_avg_landing_price, batch.total_price as b_total_price, batch.valid as b_valid, batch.pt_var1 as b_pt_var1, batch.pt_var2 as b_pt_var2
FROM `wzch_local_purchase_supply_detail` AS psd
/* 关联物资总需*/ LEFT JOIN wzch_total_demand_detail AS tdd ON tdd.valid = 1 AND tdd.del_flag = 0 AND tdd.material_code = psd.material_code AND tdd.material_standard = psd.material_standard
/* 关联优先采购物资台账*/ LEFT JOIN wzch_prior_approach_detail AS pad ON pad.del_flag = 0 AND pad.material_code = psd.material_code
/* 关联采购供应策划批次信息 */ LEFT JOIN wzch_local_purchase_supply_batch_detail as batch ON batch.purchase_supply_detail_id = psd.id

mapper.select:


    psd.`del_flag` = 0
    and psd.`purchase_supply_id` = #{purchaseSupplyId}
    and psd.`material_code` = #{materialCode}
    and psd.`material_tech_param` =
        #{materialTechParam}

    and psd.`brand` = #{brand}
    and psd.`material_standard` =
        #{materialStandard}

    and psd.`total_demand_amount` = #{totalDemandAmount}
    and psd.`self_demand_amount` = #{selfDemandAmount}
    and psd.`non_prior_approach_amount` = #{nonPriorApproachAmount}

    and psd.`batch` = #{batch}
    and psd.`plan_purchase_num` = #{planPurchaseNum}
    and psd.`plan_purchase_date` = #{planPurchaseDate}
    and psd.`source` = #{source}
    and psd.`currency` = #{currency}
    and psd.`unit_price` = #{unitPrice}
    and psd.`avg_purchase_price` = #{avgPurchasePrice}
    and psd.`avg_despatch_price` = #{avgDespatchPrice}
    and psd.`avg_cust_clear_price` = #{avgCustClearPrice}
    and psd.`avg_local_transport_price` = #{avgLocalTransportPrice}

    and psd.`avg_landing_price` = #{avgLandingPrice}
    and psd.`total_price` = #{totalPrice}
    and psd.`file_group_id` = #{fileGroupId}
    and psd.`project_id` = #{projectId}
    and psd.`project_name` like concat('%',
        #{projectName},
        '%')

    and psd.`dept_id` = #{deptId}
    and psd.`create_user` = #{createUser}
    and psd.`create_user_name` like concat('%',
        #{createUserName}, '%')

    and psd.`update_user` = #{updateUser}
    and psd.`update_user_name` like concat('%',
        #{updateUserName}, '%')

    and psd.`del_user` = #{delUser}
    and psd.`del_time` = #{delTime}
    and psd.`pt_var1` = #{ptVar1}
    and psd.`pt_var2` = #{ptVar2}
    and psd.`pt_var3` = #{ptVar3}

order by psd.`material_code` asc

