mapper.select:
SELECT temp.*, IFNULL(temp.self_demand_amount, 0) - IFNULL(temp.prior_approach_num, 0) AS non_prior_approach_amount FROM ( SELECT sd.material_code,
/*物资总需信息*/ tdd.id AS id, tdd.material_tech_param, tdd.material_standard, tdd.total_demand_amount, tdd.self_demand_amount, tdd.category_name,
/*优先进场物资信息*/ ppd.id AS ppdId, ppd.brand, pad.id AS padId, pad.prior_approach_num,
/*来源策划采购数据*/ sayc.id AS saycId, IFNULL(sum(sayc.other_state_num), 0) + IFNULL(sum(sayc.local_num), 0) AS purchase_amount
FROM wzch_source_detail AS sd LEFT JOIN wzch_source_approach_year_count AS sayc ON sd.id = sayc.detail_id
/* 关联物资总需*/ LEFT JOIN wzch_total_demand_detail AS tdd ON tdd.del_flag = 0 AND tdd.material_code = sd.material_code AND tdd.material_standard = sd.material_standard
/* 关联优先采购物资台账*/ LEFT JOIN wzch_prior_approach_detail AS pad ON pad.del_flag = 0 AND pad.material_code = sd.material_code
/* 关联优先采购物资策划*/ LEFT JOIN wzch_prior_purchase_detail AS ppd ON ppd.del_flag = 0 AND ppd.material_code = sd.material_code
WHERE sd.del_flag = '0' AND tdd.del_flag = 0 AND tdd.material_code = sd.material_code AND tdd.material_standard = sd.material_standard
GROUP BY sayc.material_code, sayc.detail_id ) AS temp WHERE temp.purchase_amount != 0 order by temp.material_code asc

SELECT sd.material_code, sd.material_standard, sum( sayc.other_state_num ) AS other_state_num, sum( sayc.local_num ) AS local_num FROM wzch_source_detail AS sd LEFT JOIN wzch_source_approach_year_count AS sayc ON sd.id = sayc.detail_id WHERE sd.material_code IN
#{code}
GROUP BY sd.material_code, sd.material_standard;
